202	+
203	+        var elektronik = result.Single(c => c.Id == "K1");
204	+        Assert.Equal("Elektronik", elektronik.Name);
205	+        Assert.Equal(2, elektronik.Subcategories.Count);
206	+        Assert.Contains(elektronik.Subcategories, s => s.Id == "K1a" && s.Name == "Kopfhörer");
207	+        Assert.Contains(elektronik.Subcategories, s => s.Id == "K1b" && s.Name == "Smartphones & Zubehör");
