+            .OrderBy(c => c.Id)
+            .Select(c => new CategoryDto
+            {
+                Id = c.Id,
+                Name = c.Name,
+                Subcategories = c.Subcategories
+                    .OrderBy(s => s.Id)
+                    .Select(s => new SubcategoryDto
