+  beforeEach(async () => {
+    categoriesApiMock = { getCategories: vi.fn() };
+    categoriesApiMock.getCategories.mockReturnValue(of(categories));
+
+    await TestBed.configureTestingModule({
+      imports: [CategoryNav],
+      providers: [{ provide: CategoriesApi, useValue: categoriesApiMock }],
