16	    protected override void OnModelCreating(ModelBuilder modelBuilder)
17	    {
18	        modelBuilder.Entity<Category>(entity =>
19	        {
20	            entity.HasKey(c => c.Id);
21	        });
22	
23	        modelBuilder.Entity<Subcategory>(entity =>
24	        {
25	            entity.HasKey(s => s.Id);
