36	            entity.HasOne(pd => pd.Subcategory)
37	                .WithMany(s => s.PropertyDefinitions)
38	                .HasForeignKey(pd => pd.SubcategoryId);
39	        });
40	
41	        modelBuilder.Entity<Product>(entity =>
42	        {
43	            entity.HasKey(p => p.Id);
44	            entity.HasIndex(p => p.SubcategoryId);
45	            entity.HasOne(p => p.Subcategory)
46	                .WithMany(s => s.Products)
47	                .HasForeignKey(p => p.SubcategoryId);
48	        });
49	
50	        modelBuilder.Entity<ProductProperty>(entity =>
51	        {
52	            entity.HasIndex(pp => pp.ProductId);
53	            entity.HasIndex(pp => pp.PropertyDefinitionId);
54	            entity.HasIndex(pp => new { pp.ProductId, pp.PropertyDefinitionId }).IsUnique();
55	            entity.HasOne(pp => pp.Product)
56	                .WithMany(p => p.ProductProperties)
