70	        {
71	            entity.HasIndex(o => o.ProductId);
72	            entity.HasIndex(o => o.SupplierId);
73	            entity.Property(o => o.Price).HasColumnType("decimal(10,2)");
74	            entity.HasOne(o => o.Product)
75	                .WithMany(p => p.Offers)
76	                .HasForeignKey(o => o.ProductId);
77	            entity.HasOne(o => o.Supplier)
78	                .WithMany(s => s.Offers)
