1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Dtos;
4	
5	namespace seed_b_backend.Api.Application;
6	
7	public class ProductQueryService(AppDbContext db)
8	{
9	    private const int PageSize = 20;
10	
11	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(
12	        int page = 1,
13	        string? categoryId = null,
14	        string? subcategoryId = null,
15	        CancellationToken cancellationToken = default)
16	    {
17	        if (page < 1)
18	        {
19	            page = 1;
20	        }
21	
22	        var query = db.Products.AsNoTracking().AsQueryable();
23	
24	        if (!string.IsNullOrEmpty(subcategoryId))
25	        {
26	            query = query.Where(p => p.SubcategoryId == subcategoryId);
27	        }
28	        else if (!string.IsNullOrEmpty(categoryId))
29	        {
30	            query = query.Where(p => p.Subcategory.CategoryId == categoryId);
31	        }
32	
33	        query = query.OrderBy(p => p.Id);
34	
35	        var totalCount = await query.CountAsync(cancellationToken);
36	        var pageCount = totalCount == 0 ? 0 : (int)Math.Ceiling(totalCount / (double)PageSize);
37	
38	        if (pageCount > 0 && page > pageCount)
39	        {
40	            page = pageCount;
41	        }
42	
43	        var items = await query
44	            .Skip((page - 1) * PageSize)
45	            .Take(PageSize)
46	            .Select(p => new ProductListItemDto
47	            {
48	                Id = p.Id,
49	                Name = p.Name,
50	                LowestPrice = p.Offers.Select(o => (decimal?)o.Price).Min()
51	            })
52	            .ToListAsync(cancellationToken);
53	
54	        return new PagedResultDto<ProductListItemDto>
55	        {
56	            Items = items,
57	            TotalCount = totalCount,
58	            PageCount = pageCount,
59	            Page = page,
60	            PageSize = PageSize
61	        };
62	    }
63	}
