    nextButton.click();
    fixture.detectChanges();

    expect(productsApiMock.getProducts).toHaveBeenLastCalledWith(2, 'K1', undefined);
    expect(compiled.querySelector('.product-list__name')?.textContent).toBe('Produkt 2b');
